{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "The closest-scoring analogue, 5-fluorouridine (OGT 719), has an absolute oral bioavailability of approximately 25% in patients, which is above the 20% threshold and supports high bioavailability for this ribonucleoside scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Fludarabine, a purine nucleoside analogue, shows absolute oral bioavailability of about 55% in patients, demonstrating that polar purine nucleosides can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Ribavirin, a polar ribonucleoside analogue, has an absolute oral bioavailability of about 55% in healthy adults, supporting that high polarity does not preclude F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Netivudine (882C87), a uracil nucleoside analogue, has an absolute oral bioavailability of 24.6% in elderly volunteers, just above the threshold and consistent with high for similar nucleosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Cladribine, a purine nucleoside, has an oral bioavailability of about 36% (25-68%) in patients, further supporting moderate-to-good absorption for purine nucleosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Uridine, a closely related ribonucleoside, has low oral bioavailability (5.8-9.9%) in humans, which argues for low; however, the query's purine base and fused ring system differ from uridine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Levovirin, the L-enantiomer of ribavirin, has <10% oral bioavailability, but this is attributed to poor recognition of L-nucleosides; the query has the natural D-ribose configuration.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C28"],
      "claim": "NHC, a cytidine analogue, has poor human bioavailability, but it is a pyrimidine with an N-hydroxy modification, making it less transferable to the purine query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polar D-ribofuranosyl purine nucleoside. The most transferable experimental evidence from purine nucleoside analogues (fludarabine, ribavirin, cladribine) shows moderate-to-good oral bioavailability (35-60%), and the closest-scoring analogue 5-fluorouridine has F ~25%, above the 20% threshold. Low-bioavailability examples are mostly pyrimidine nucleosides (uridine, NHC) or L-nucleosides (levovirin), which are less transferable to this D-ribosyl purine. Therefore, F >=20% is better supported.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for the exact query molecule; all evidence is from analogues with Morgan similarity <=0.34.",
    "The query contains an unusual N-ribosylamine linkage and a xanthine-like purine base; no direct analogue with this exact connectivity was retrieved.",
    "Human data are mostly from cancer patients or healthy volunteers; formulation and dose effects may differ."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

